  q(PARA,'Which parasite is seen on a wet mount with jerky, twitching motion?','Trichomonas vaginalis',['Giardia lamblia cyst','Taenia saginata egg','Plasmodium vivax'],'A','Trichomonas is a flagellated protozoan that causes a sexually transmitted infection.',EST),
  q(PARA,'Eating undercooked beef can transmit which tapeworm?','Taenia saginata',['Taenia solium','Diphyllobothrium latum','Echinococcus granulosus'],'B','Taenia solium comes from pork and Diphyllobothrium from raw fish.',EST)
